  <script>
    const form = document.getElementById("addressForm");
    const toast = document.getElementById("toast");
    const fields = ["building", "street", "area", "phone"];

    function showError(id, visible) {
      const input = document.getElementById(id);
      const error = document.getElementById(id + "Error");
      input.setAttribute("aria-invalid", visible ? "true" : "false");
      error.classList.toggle("visible", visible);
    }

    function normalizeDigits(value) {
      return value
        .replace(/[٠-٩]/g, digit => String(digit.charCodeAt(0) - 0x0660))
        .replace(/[۰-۹]/g, digit => String(digit.charCodeAt(0) - 0x06F0));
    }

    fields.forEach(id => {
      const input = document.getElementById(id);
      input.addEventListener("input", () => {
        if (input.getAttribute("aria-invalid") === "true") showError(id, false);
      });
    });

    form.addEventListener("submit", event => {
      event.preventDefault();
      let firstInvalid = null;

      fields.forEach(id => {
        const input = document.getElementById(id);
        const value = input.value.trim();
        let invalid = value === "";

        if (id === "phone" && !invalid) {
          const normalized = normalizeDigits(value).replace(/[\s()-]/g, "");
          const localNumber = normalized.startsWith("+971")
            ? normalized.slice(4).replace(/^0/, "")
            : normalized.replace(/^0/, "");
          invalid = !/^(5[0-9]|6[0-9]|7[0-9])\d{7}$/.test(localNumber);
        }

        showError(id, invalid);
        if (invalid && !firstInvalid) firstInvalid = input;
      });

      if (firstInvalid) {
        firstInvalid.focus();
        return;
      }

      const button = form.querySelector(".save-button");
      button.disabled = true;
      button.textContent = "جارٍ حفظ العنوان…";

      setTimeout(() => {
        button.disabled = false;
        button.innerHTML = `
          <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M5 4h12l2 2v14H5V4Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/>
            <path d="M8 4v6h8V4M8 20v-6h8v6" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/>
          </svg>
          حفظ العنوان
        `;
        toast.classList.add("show");
        setTimeout(() => toast.classList.remove("show"), 3000);
      }, 500);
    });
  </script>
</body>
